function options(){const o={};if($('range')){if(tool.id==='remove'&&!$('range').value.trim())throw Error('Select at least one page to remove.');if(selectable()&&selected.size===0)throw Error('Select at least one page.');o.pages=$('range').value;parsePages(o.pages,items[0].meta.pages);}if(tool.id==='organize'){o.order=order.filter(i=>selected.has(i));if(!o.order.length)throw Error('Keep at least one page.');}if($('separate'))o.separate=$('separate').value==='yes';if($('angle'))o.angle=Number($('angle').value);if($('watermark'))o.text=$('watermark').value;if($('orientation'))o.orientation=$('orientation').value;if($('margin'))o.margin=$('margin').checked;return o;}
async function convertJpg(o){const indices=parsePages(o.pages||'',items[0].meta.pages);if(indices.length>40)throw Error('Select up to 40 pages for JPG conversion.');const g=generation;const doc=await openPreview(items[0].file);const output=[];let bytesTotal=0;
 try{for(let i=0;i<indices.length;i++){if(g!==generation)throw Error('Task cancelled.');const page=await doc.getPage(indices[i]+1),raw=page.getViewport({scale:1}),scale=Math.min(2,2000/Math.max(raw.width,raw.height));if(!Number.isFinite(scale)||scale<=0)throw Error('Invalid PDF page dimensions.');const viewport=page.getViewport({scale}),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(viewport.width));canvas.height=Math.max(1,Math.round(viewport.height));await page.render({canvasContext:canvas.getContext('2d'),viewport,background:'rgb(255,255,255)'}).promise;const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',Number($('quality').value)));if(!blob||blob.type!=='image/jpeg')throw Error('JPG encoding is unsupported in this browser.');const bytes=new Uint8Array(await blob.arrayBuffer());bytesTotal+=bytes.length;if(bytesTotal>100*1024*1024)throw Error('The generated images exceed 100 MiB. Choose fewer pages.');output.push({name:`page-${String(indices[i]+1).padStart(3,'0')}.jpg`,bytes});canvas.width=1;canvas.height=1;page.cleanup();$('progress').value=Math.round((i+1)/indices.length*90);}if(g!==generation)throw Error('Task cancelled.');return await task({action:'zip',files:output});}finally{await doc.destroy();}}
